package com.saumyasolar.repo;import com.saumyasolar.domain.Warranty;import org.springframework.data.jpa.repository.JpaRepository;import java.util.List;import java.util.UUID;import java.time.LocalDate;
public interface WarrantyRepository extends JpaRepository<Warranty,UUID>{List<Warranty> findByStatusAndEndDateBefore(String status,LocalDate date);List<Warranty> findByStatusAndEndDate(String status,LocalDate date);List<Warranty> findByTenantIdOrderByStartDateDesc(UUID tenantId);List<Warranty> findByTenantIdAndCustomerIdOrderByStartDateDesc(UUID tenantId,UUID customerId);}